// Las cifras vienen de SQL; la IA solo las interpreta.
const m = $('Leer métricas 24 h').first().json;
const p = $('Leer prompt P4').first().json;
return [{ json: { metricas: m, body: { model: 'gpt-4o-mini', temperature: 0.2, messages: [ { role: 'system', content: p.texto }, { role: 'user', content: JSON.stringify(m) } ] } } }];

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const texto = $('P4 · Resumen del líder').first().json.choices[0].message.content;
const m = $('Armar llamada P4').first().json.metricas || {};
const titulos = ['Estado:', 'SLA en riesgo:', 'Incidentes:', 'Patrones:', 'Calidad de la IA:', 'Prioridad de hoy:'];
let cuerpo = esc(texto);
for (const t of titulos) cuerpo = cuerpo.split(t).join('<b>' + t + '</b>');
// Detalle fijo desde SQL: números de caso, desde cuándo ocurre y destino de cada patrón (no lo escribe la IA)
const lista = (v) => Array.isArray(v) ? v : (typeof v === 'string' ? JSON.parse(v || '[]') : []);
const casos = (arr) => (arr || []).map(x => '#' + x).join(', ');

// Gestión de casos (24 h): calculada en SQL (v_graficas_diarias.gestion_24h), no por la IA
const ge = $('Armar gráficas').first().json.gestion || {};
const cs = ge.casos || {};
const linea = (icono, nombre, k) => (ge[k] || 0) > 0 ? '\n   ' + icono + ' ' + nombre + ': ' + ge[k] + ' · ' + esc(casos(cs[k])) : '';
const kb = (ge.kb_resuelto || 0) + (ge.kb_por_aprobar || 0);
const interno = (ge.interno_ingenieria || 0) + (ge.interno_datos || 0) + (ge.interno_manual || 0);
const gestion = (ge.total || 0) === 0 ? '' :
  '\n\n<b>Gestión de casos (24 h)</b>' +
  '\n🤖 Con base de conocimiento: ' + kb + ' de ' + ge.total + ' (' + (ge.pct_kb ?? 0) + '%)' +
  linea('✅', 'Resueltos (borrador IA aprobado)', 'kb_resuelto') +
  linea('🕓', 'Borrador listo, por aprobar', 'kb_por_aprobar') +
  '\n🛠 En gestión interna: ' + interno +
  linea('🔧', 'Escalados a Ingeniería', 'interno_ingenieria') +
  linea('⏳', 'Esperando datos del cliente', 'interno_datos') +
  linea('✍️', 'Borrador rechazado (manual)', 'interno_manual');

const det = [];
const ejemplos = [];
// Un renglón por incidente (SQL ya agrupa las oleadas del mismo problema)
for (const i of lista(m.incidentes)) {
  ejemplos.push(...(i.casos || []));
  const oleadas = Number(i.oleadas || 1) > 1 ? ' · llegó en ' + i.oleadas + ' oleadas' : '';
  det.push('🚨 <b>' + esc(i.firma === 'fuente_externa' ? 'Fuente externa' : 'Plataforma') + '</b> · ' + esc(i.producto) + ' ' + esc(i.pais) +
    (i.codigo ? ' · ' + esc(i.codigo) : '') + ' · ' + esc(i.tickets) + ' casos (' + esc(casos(i.casos)) + ')' +
    ' · desde ' + esc(i.desde) + oleadas + ' (' + esc(i.estado) + ')');
}
for (const s of lista(m.sla_en_riesgo)) {
  ejemplos.push(s.caso);
  det.push('⏱ #' + esc(s.caso) + ' ' + esc(s.severidad) + ' · ' + esc(s.cliente) + ' · desde ' + esc(s.desde) +
    ' · ' + esc(s.minutos_abierto) + ' de ' + esc(s.limite_min) + ' min');
}
for (const p of lista(m.patrones)) {
  ejemplos.push(...(p.casos || []));
  det.push('🔁 ' + esc(p.patron) + ' · casos ' + esc(casos(p.casos)) + ' → <b>' + esc(p.destino || 'sin destino') + '</b>');
}
const detalle = det.length ? '\n\n<b>Casos a revisar</b>\n' + det.slice(0, 15).join('\n') +
  (ejemplos.length ? '\n\n💬 Pregunta por uno: <code>caso ' + esc(ejemplos[0]) + '</code> y tu pregunta.' : '') : '';
const fecha = $now.setZone('America/Bogota').toFormat('dd/MM HH:mm');
return [{ json: { mensaje: '☀️ <b>Resumen de soporte · ' + fecha + '</b>\n\n' + cuerpo + gestion + detalle } }];

// El mismo resumen de Telegram, en HTML para correo, con la paleta pública de Truora (sin logo) y las 4 gráficas.
const dest = Object.fromEntries($('Leer destinatarios').all().map(i => [i.json.rol, i.json.correo]));
const msg = $('Componer resumen').first().json.mensaje;
const gr = $('Armar gráficas').first().json;
const fecha = $now.setZone('America/Bogota').setLocale('es').toFormat("cccc d 'de' LLLL yyyy");
const hora = $now.setZone('America/Bogota').toFormat('HH:mm');
// Cuerpo: se quita la primera línea (el título va en el encabezado) y se aplica estilo
const cuerpo = msg.replace(/^[^\n]*\n\n/, '')
  .replace(/<code>/g, '<code style="background:#F2EEFF;color:#3C1AE9;padding:1px 6px;border-radius:4px">')
  .replace(/\n/g, '<br>');
const imgs = (gr.urls || []).map((u, i) =>
  '<div style="margin:0 0 18px"><div style="font-size:13px;font-weight:bold;color:#01022E;margin:0 0 6px">' + gr.titulos[i] + '</div>' +
  '<img src="' + u.replace(/&/g, '&amp;') + '" alt="' + gr.titulos[i] + '" width="632" style="display:block;width:100%;max-width:632px;height:auto;border:1px solid #E8EBF3;border-radius:6px"></div>').join('');
const html =
  '<div style="background:#F5F6FB;padding:24px 12px;font-family:Arial,Helvetica,sans-serif">' +
  '<div style="max-width:680px;margin:0 auto;background:#FFFFFF;border:1px solid #E8EBF3;border-radius:10px;overflow:hidden">' +
  '<div style="background:#01022E;padding:22px 24px">' +
    '<div style="font-size:12px;letter-spacing:1.5px;text-transform:uppercase;color:#9BD2F3">Soporte · Resumen diario del líder</div>' +
    '<div style="font-size:22px;font-weight:bold;color:#FFFFFF;margin-top:6px">' + fecha + '</div>' +
    '<div style="font-size:13px;color:#CBD5E1;margin-top:2px">Corte ' + hora + ' (hora Bogotá) · últimas 24 h · ' + (gr.tickets_24h ?? 0) + ' tickets</div>' +
  '</div>' +
  '<div style="height:4px;background:#EE792F"></div>' +
  '<div style="padding:22px 24px;font-size:14px;line-height:1.6;color:#01022E">' + cuerpo + '</div>' +
  '<div style="padding:0 24px 8px"><div style="font-size:16px;font-weight:bold;color:#3C1AE9;border-top:1px solid #E8EBF3;padding-top:18px;margin-bottom:14px">📊 Gráficas</div>' + imgs + '</div>' +
  '<div style="background:#F9FAFE;border-top:1px solid #E8EBF3;padding:14px 24px;font-size:12px;color:#64748B;line-height:1.5">' +
    'Cifras calculadas en SQL (v_resumen_diario y v_graficas_diarias); la IA solo las redacta. Gráficas generadas con QuickChart a partir de conteos agregados, sin datos de tickets. DEMO: datos sintéticos.' +
  '</div></div></div>';
return [{ json: { para: dest.lider, asunto: 'Resumen de soporte · ' + $now.setZone('America/Bogota').setLocale('es').toFormat('ccc d LLL yyyy'), html } }];

// Gráficas a partir de conteos agregados en SQL (v_graficas_diarias). No viaja texto de tickets ni datos personales.
// Paleta tomada del sitio público de Truora (sin logos). Chart.js v2 en QuickChart; la config va como JS para usar funciones.
// URLs completas: no vencen (las cortas gratuitas vencen a los 3 días).
const g = $('Leer datos de gráficas').first().json || {};
const arr = (v) => Array.isArray(v) ? v : (typeof v === 'string' ? JSON.parse(v || '[]') : []);
const obj = (v) => (v && typeof v === 'object') ? v : (typeof v === 'string' ? JSON.parse(v || '{}') : {});
const J = JSON.stringify;
const C = { morado: '#3C1AE9', naranja: '#EE792F', marino: '#01022E', celeste: '#9BD2F3', moradoClaro: '#A99BF5', naranjaClaro: '#F6B98F', gris: '#CBD5E1' };
const CLAROS = [C.celeste, C.moradoClaro, C.naranjaClaro, C.gris];
const GRID = '#E8EBF3', TICK = '#475569';
const url = (cfg) => 'https://quickchart.io/chart?w=900&h=500&bkg=white&f=png&c=' + encodeURIComponent(cfg);

// Piezas comunes (texto JS, no JSON, para poder pasar funciones a datalabels)
const DL_SHOW = 'function(c){return c.dataset.data[c.dataIndex]>0}';
const DL_COLOR = 'function(c){var b=c.dataset.backgroundColor;b=Array.isArray(b)?b[c.dataIndex]:b;return ' + J(CLAROS) + '.indexOf(b)>=0?"' + C.marino + '":"#FFFFFF"}';
const titulo = (t) => 'title:{display:true,text:' + J(t) + ',fontSize:20,fontStyle:"bold",fontColor:"' + C.marino + '",padding:20}';
const leyenda = (pos) => 'legend:{position:"' + pos + '",labels:{fontColor:"#334155",fontSize:14,boxWidth:14,padding:18}}';
const eje = (stacked, grid) => '{stacked:' + stacked + ',gridLines:{display:' + grid + ',color:"' + GRID + '",zeroLineColor:"' + GRID + '",drawBorder:false},ticks:{beginAtZero:true,precision:0,fontColor:"' + TICK + '",fontSize:14,padding:6}}';
const etiquetasBarras = 'datalabels:{display:' + DL_SHOW + ',color:' + DL_COLOR + ',font:{weight:"bold",size:15}}';

// 0) Gestión de casos: base de conocimiento vs interna (dona con número y porcentaje)
const ge = obj(g.gestion_24h);
const total = Number(ge.total || 0);
const pct = (n) => total ? Math.round(100 * n / total) : 0;
const cats = [
  ['kb_resuelto', 'KB · resuelto', C.morado],
  ['kb_por_aprobar', 'KB · por aprobar', C.moradoClaro],
  ['interno_ingenieria', 'Interno · Ingeniería', C.naranja],
  ['interno_datos', 'Interno · esperando datos', C.naranjaClaro],
  ['interno_manual', 'Interno · manual', C.marino]
].filter(([k]) => Number(ge[k] || 0) > 0);
const v0 = cats.length ? cats.map(c => Number(ge[c[0]])) : [1];
const c0 = '{type:"doughnut",data:{labels:' + J(cats.length ? cats.map(c => c[1] + ': ' + ge[c[0]] + ' (' + pct(ge[c[0]]) + '%)') : ['Sin casos']) +
  ',datasets:[{data:' + J(v0) + ',backgroundColor:' + J(cats.length ? cats.map(c => c[2]) : [C.gris]) + ',borderColor:"#FFFFFF",borderWidth:4}]},' +
  'options:{cutoutPercentage:58,layout:{padding:{left:10,right:10,top:0,bottom:10}},' +
  titulo('Gestión de casos · 24 h · ' + (ge.pct_kb ?? 0) + '% con base de conocimiento') + ',' + leyenda('right') + ',' +
  'plugins:{datalabels:{display:' + DL_SHOW + ',color:' + DL_COLOR + ',font:{weight:"bold",size:16},textAlign:"center",' +
  'formatter:function(v,c){var t=c.dataset.data.reduce(function(a,b){return a+b},0);return [v,Math.round(100*v/t)+"%"]}},' +
  'doughnutlabel:{labels:[{text:"' + total + '",font:{size:40,weight:"bold"},color:"' + C.marino + '"},{text:"casos",font:{size:15},color:"#64748B"}]}}}}';

// 1) Origen de la falla x severidad (barras horizontales apiladas)
const nombres = { truora: 'Truora (plataforma)', fuente_externa_gobierno: 'Fuente gobierno', meta_whatsapp: 'Meta / WhatsApp', integracion_cliente: 'Integración cliente', usuario_final: 'Usuario final', no_aplica: 'No aplica', indeterminado: 'Indeterminado', sin_clasificar: 'Sin clasificar' };
const colSev = { P1: C.naranja, P2: C.morado, P3: C.celeste, P4: C.gris };
const os = arr(g.origen_severidad);
const tot = (x) => ['P1', 'P2', 'P3', 'P4'].reduce((s, k) => s + Number(x[k] || 0), 0);
const sev1 = ['P1', 'P2', 'P3', 'P4'].filter(s => os.some(x => Number(x[s] || 0) > 0));
const c1 = '{type:"horizontalBar",data:{labels:' + J(os.length ? os.map(x => (nombres[x.origen] || x.origen) + ' (' + tot(x) + ')') : ['Sin tickets']) +
  ',datasets:' + J(sev1.map(s => ({ label: s, backgroundColor: colSev[s], maxBarThickness: 56, data: os.map(x => Number(x[s] || 0)) }))) + '},' +
  'options:{' + titulo('Tickets 24 h por origen de la falla y severidad') + ',' + leyenda('bottom') + ',layout:{padding:{right:20}},' +
  'scales:{xAxes:[' + eje(true, true) + '],yAxes:[' + eje(true, false) + ']},plugins:{' + etiquetasBarras + '}}}';

// 2) SLA por severidad (barras verticales apiladas)
const sl = arr(g.sla_por_severidad);
const est = [['en_plazo', 'En plazo', C.morado], ['en_riesgo', 'En riesgo (>80%)', C.naranjaClaro], ['vencido', 'Vencido', C.naranja]];
const c2 = '{type:"bar",data:{labels:' + J(sl.length ? sl.map(x => x.severidad) : ['Sin tickets']) +
  ',datasets:' + J(est.map(([k, l, col]) => ({ label: l, backgroundColor: col, maxBarThickness: 90, data: sl.map(x => Number(x[k] || 0)) }))) + '},' +
  'options:{' + titulo('SLA por severidad · últimas 24 h') + ',' + leyenda('bottom') + ',' +
  'scales:{xAxes:[' + eje(true, false) + '],yAxes:[' + eje(true, true) + ']},plugins:{' + etiquetasBarras + '}}}';

// 3) Tendencia 7 días: total vs escalados a Ingeniería (línea con valores)
const td = arr(g.tendencia_7d);
const maxY = Math.max(1, ...td.map(x => Number(x.total || 0)));
const c3 = '{type:"line",data:{labels:' + J(td.map(x => x.dia)) + ',datasets:' + J([
  { label: 'Tickets', borderColor: C.morado, backgroundColor: 'rgba(60,26,233,0.10)', fill: true, borderWidth: 3, pointRadius: 5, pointBackgroundColor: C.morado, cubicInterpolationMode: 'monotone', data: td.map(x => Number(x.total || 0)) },
  { label: 'Escalados a Ingeniería', borderColor: C.naranja, backgroundColor: C.naranja, fill: false, borderWidth: 3, pointRadius: 5, pointBackgroundColor: C.naranja, cubicInterpolationMode: 'monotone', data: td.map(x => Number(x.escalados || 0)) }
]) + '},options:{' + titulo('Tickets por día · últimos 7 días') + ',' + leyenda('bottom') + ',' +
  'scales:{xAxes:[' + eje(false, false) + '],yAxes:[{gridLines:{color:"' + GRID + '",zeroLineColor:"' + GRID + '",drawBorder:false},ticks:{beginAtZero:true,precision:0,suggestedMax:' + Math.ceil(maxY * 1.25) + ',fontColor:"' + TICK + '",fontSize:14}}]},' +
  'plugins:{datalabels:{display:' + DL_SHOW + ',align:"top",anchor:"end",offset:4,color:function(c){return c.dataset.borderColor},font:{weight:"bold",size:15}}}}}';

const titulos = ['Gestión de casos: base de conocimiento vs interna (24 h)', 'Origen de la falla y severidad (24 h)', 'SLA por severidad (24 h)', 'Tendencia 7 días'];
return [{ json: { tickets_24h: g.tickets_24h ?? 0, gestion: ge, titulos, urls: [url(c0), url(c1), url(c2), url(c3)] } }];
